-- EduFace schema V001 — MySQL 8.x, InnoDB, utf8mb4
-- Forward-engineerable in MySQL Workbench (File > Run SQL Script / Reverse Engineer).
-- Same script runs on the central server and on every school edge node.
--
-- Conventions
--   * PK = CHAR(36) UUID (v4/v7), generated by the app, never AUTO_INCREMENT -> no cross-site collisions.
--   * Every synced table has: school_id, created_at, updated_at, version, deleted_at (soft delete).
--   * Every write ALSO inserts a sync_outbox row in the same transaction (done by the app layer).
--   * Timestamps are UTC, DATETIME(3).

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS eduface CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE eduface;

-- ---------------------------------------------------------------- schools
CREATE TABLE schools (
  id            CHAR(36)     NOT NULL,
  code          VARCHAR(32)  NOT NULL,
  name          VARCHAR(200) NOT NULL,
  logo_path     VARCHAR(255) NULL,
  primary_color CHAR(7)      NULL,
  timezone      VARCHAR(64)  NOT NULL DEFAULT 'Africa/Kampala',
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version       INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at    DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_schools_code (code)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- roles
CREATE TABLE roles (
  id          CHAR(36)    NOT NULL,
  school_id   CHAR(36)    NULL,                 -- NULL = global/system role
  name        VARCHAR(50) NOT NULL,             -- SuperAdmin, SchoolAdmin, Teacher, Security, Parent
  permissions JSON        NOT NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version     INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at  DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_roles_school_name (school_id, name),
  CONSTRAINT fk_roles_school FOREIGN KEY (school_id) REFERENCES schools(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- users (staff accounts)
CREATE TABLE users (
  id              CHAR(36)     NOT NULL,
  school_id       CHAR(36)     NOT NULL,
  role_id         CHAR(36)     NOT NULL,
  email           VARCHAR(190) NOT NULL,
  full_name       VARCHAR(150) NOT NULL,
  phone           VARCHAR(32)  NULL,
  password_hash   VARCHAR(255) NOT NULL,        -- PBKDF2 or Argon2id hash (never the password)
  totp_secret_enc VARBINARY(128) NULL,          -- optional 2FA, AES-256-GCM encrypted
  failed_logins   TINYINT UNSIGNED NOT NULL DEFAULT 0,
  locked_until    DATETIME(3)  NULL,
  last_login_at   DATETIME(3)  NULL,
  is_active       TINYINT(1)   NOT NULL DEFAULT 1,
  staff_clock_enabled TINYINT(1) NOT NULL DEFAULT 0,  -- optional staff face clock-in
  created_at      DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at      DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version         INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at      DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_school_email (school_id, email),
  KEY ix_users_role (role_id),
  CONSTRAINT fk_users_school FOREIGN KEY (school_id) REFERENCES schools(id),
  CONSTRAINT fk_users_role   FOREIGN KEY (role_id)   REFERENCES roles(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- classes
CREATE TABLE classes (
  id          CHAR(36)     NOT NULL,
  school_id   CHAR(36)     NOT NULL,
  name        VARCHAR(60)  NOT NULL,            -- e.g. "S.2"
  stream      VARCHAR(30)  NULL,                -- e.g. "East"
  academic_year SMALLINT UNSIGNED NOT NULL,
  teacher_id  CHAR(36)     NULL,
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version     INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at  DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_classes (school_id, academic_year, name, stream),
  CONSTRAINT fk_classes_school  FOREIGN KEY (school_id)  REFERENCES schools(id),
  CONSTRAINT fk_classes_teacher FOREIGN KEY (teacher_id) REFERENCES users(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- students
CREATE TABLE students (
  id            CHAR(36)     NOT NULL,
  school_id     CHAR(36)     NOT NULL,
  class_id      CHAR(36)     NULL,
  student_no    VARCHAR(40)  NOT NULL,
  first_name    VARCHAR(80)  NOT NULL,
  last_name     VARCHAR(80)  NOT NULL,
  gender        ENUM('M','F','O') NULL,
  date_of_birth DATE         NULL,
  photo_path    VARCHAR(255) NULL,              -- profile thumbnail only (consent-gated); NOT used for matching
  qr_token      CHAR(32)     NULL,              -- non-biometric alternative (card/QR)
  status        ENUM('active','graduated','withdrawn','suspended') NOT NULL DEFAULT 'active',
  status_changed_at DATETIME(3) NULL,           -- drives retention purge
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version       INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at    DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_students_no (school_id, student_no),
  UNIQUE KEY uq_students_qr (qr_token),
  KEY ix_students_class (class_id),
  KEY ix_students_name (school_id, last_name, first_name),
  CONSTRAINT fk_students_school FOREIGN KEY (school_id) REFERENCES schools(id),
  CONSTRAINT fk_students_class  FOREIGN KEY (class_id)  REFERENCES classes(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- guardians
CREATE TABLE guardians (
  id          CHAR(36)     NOT NULL,
  school_id   CHAR(36)     NOT NULL,
  full_name   VARCHAR(150) NOT NULL,
  phone       VARCHAR(32)  NULL,
  email       VARCHAR(190) NULL,
  whatsapp    VARCHAR(32)  NULL,
  preferred_channel ENUM('sms','email','whatsapp') NOT NULL DEFAULT 'sms',
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version     INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at  DATETIME(3)  NULL,
  PRIMARY KEY (id),
  KEY ix_guardians_phone (school_id, phone),
  CONSTRAINT fk_guardians_school FOREIGN KEY (school_id) REFERENCES schools(id)
) ENGINE=InnoDB;

CREATE TABLE student_guardians (
  id           CHAR(36)    NOT NULL,
  school_id    CHAR(36)    NOT NULL,
  student_id   CHAR(36)    NOT NULL,
  guardian_id  CHAR(36)    NOT NULL,
  relationship VARCHAR(40) NULL,
  is_primary   TINYINT(1)  NOT NULL DEFAULT 0,
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version      INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at   DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_sg (student_id, guardian_id),
  KEY ix_sg_guardian (guardian_id),
  CONSTRAINT fk_sg_student  FOREIGN KEY (student_id)  REFERENCES students(id),
  CONSTRAINT fk_sg_guardian FOREIGN KEY (guardian_id) REFERENCES guardians(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- consent
CREATE TABLE consent_records (
  id            CHAR(36)    NOT NULL,
  school_id     CHAR(36)    NOT NULL,
  student_id    CHAR(36)    NOT NULL,
  guardian_id   CHAR(36)    NOT NULL,
  purpose       ENUM('biometric_attendance','photo','notifications') NOT NULL,
  status        ENUM('granted','withdrawn') NOT NULL,
  policy_version VARCHAR(20) NOT NULL,
  evidence_path VARCHAR(255) NULL,              -- scanned form / signature
  recorded_by   CHAR(36)    NULL,
  granted_at    DATETIME(3) NOT NULL,
  withdrawn_at  DATETIME(3) NULL,
  created_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version       INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at    DATETIME(3) NULL,
  PRIMARY KEY (id),
  KEY ix_consent_student (student_id, purpose, status),
  CONSTRAINT fk_consent_student  FOREIGN KEY (student_id)  REFERENCES students(id),
  CONSTRAINT fk_consent_guardian FOREIGN KEY (guardian_id) REFERENCES guardians(id),
  CONSTRAINT fk_consent_user     FOREIGN KEY (recorded_by) REFERENCES users(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- face embeddings
-- Only embeddings are stored (no raw face images). 512-d float32 = 2048 bytes, AES-256-GCM
-- encrypted by the app: embedding_enc = nonce(12) || ciphertext(2048) || tag(16) => 2076 bytes.
CREATE TABLE face_embeddings (
  id            CHAR(36)     NOT NULL,
  school_id     CHAR(36)     NOT NULL,
  subject_type  ENUM('student','staff') NOT NULL DEFAULT 'student',
  student_id    CHAR(36)     NULL,
  user_id       CHAR(36)     NULL,
  embedding_enc VARBINARY(2200) NOT NULL,
  key_id        VARCHAR(32)  NOT NULL,          -- which data-encryption key (rotation)
  model_name    VARCHAR(40)  NOT NULL,          -- e.g. 'arcface_r50_w600k'
  model_version VARCHAR(20)  NOT NULL,
  quality_score DECIMAL(5,4) NULL,
  captured_at   DATETIME(3)  NOT NULL,
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version       INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at    DATETIME(3)  NULL,
  PRIMARY KEY (id),
  KEY ix_fe_student (student_id),
  KEY ix_fe_user (user_id),
  KEY ix_fe_school_model (school_id, model_name, model_version),
  CONSTRAINT fk_fe_student FOREIGN KEY (student_id) REFERENCES students(id),
  CONSTRAINT fk_fe_user    FOREIGN KEY (user_id)    REFERENCES users(id),
  CONSTRAINT ck_fe_subject CHECK (
    (subject_type='student' AND student_id IS NOT NULL AND user_id IS NULL) OR
    (subject_type='staff'   AND user_id IS NOT NULL AND student_id IS NULL))
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- devices
CREATE TABLE devices (
  id             CHAR(36)     NOT NULL,
  school_id      CHAR(36)     NOT NULL,
  name           VARCHAR(80)  NOT NULL,         -- "Main Gate", "S.2 East tablet"
  kind           ENUM('gate','classroom','visitor_desk','edge_node') NOT NULL,
  direction      ENUM('in','out','both') NOT NULL DEFAULT 'in',
  pairing_code_hash VARCHAR(255) NULL,          -- one-time pairing secret (hashed)
  api_key_hash   VARCHAR(255) NULL,             -- issued after pairing
  cert_fingerprint CHAR(64)   NULL,
  status         ENUM('pending','active','revoked') NOT NULL DEFAULT 'pending',
  last_seen_at   DATETIME(3)  NULL,
  config         JSON         NULL,             -- thresholds, camera URL, etc.
  created_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version        INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at     DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_devices_name (school_id, name),
  CONSTRAINT fk_devices_school FOREIGN KEY (school_id) REFERENCES schools(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- attendance_events (append-only)
-- One row per scan / override. Daily status is derived from these (+ cutoff in settings).
CREATE TABLE attendance_events (
  id            CHAR(36)     NOT NULL,
  school_id     CHAR(36)     NOT NULL,
  subject_type  ENUM('student','staff') NOT NULL DEFAULT 'student',
  student_id    CHAR(36)     NULL,
  user_id       CHAR(36)     NULL,
  device_id     CHAR(36)     NULL,              -- NULL for manual entries
  event_date    DATE         NOT NULL,          -- school-local date (denormalised for fast filters)
  occurred_at   DATETIME(3)  NOT NULL,          -- UTC
  direction     ENUM('in','out') NOT NULL,
  status        ENUM('present','late','absent','excused','early_departure') NOT NULL,
  method        ENUM('face','qr','manual') NOT NULL,
  confidence    DECIMAL(5,4) NULL,
  liveness_score DECIMAL(5,4) NULL,
  override_by   CHAR(36)     NULL,
  override_reason VARCHAR(255) NULL,            -- required when method='manual'
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version       INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at    DATETIME(3)  NULL,
  PRIMARY KEY (id),
  KEY ix_ae_date_school   (school_id, event_date, status),
  KEY ix_ae_student_date  (student_id, event_date),
  KEY ix_ae_user_date     (user_id, event_date),
  KEY ix_ae_device_time   (device_id, occurred_at),
  CONSTRAINT fk_ae_student  FOREIGN KEY (student_id)  REFERENCES students(id),
  CONSTRAINT fk_ae_user     FOREIGN KEY (user_id)     REFERENCES users(id),
  CONSTRAINT fk_ae_device   FOREIGN KEY (device_id)   REFERENCES devices(id),
  CONSTRAINT fk_ae_override FOREIGN KEY (override_by) REFERENCES users(id),
  CONSTRAINT ck_ae_subject CHECK (
    (subject_type='student' AND student_id IS NOT NULL) OR
    (subject_type='staff'   AND user_id IS NOT NULL)),
  CONSTRAINT ck_ae_manual CHECK (method <> 'manual' OR (override_by IS NOT NULL AND override_reason IS NOT NULL))
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- visitors / visits / badges
CREATE TABLE visitors (
  id            CHAR(36)     NOT NULL,
  school_id     CHAR(36)     NOT NULL,
  full_name     VARCHAR(150) NOT NULL,
  phone         VARCHAR(32)  NULL,
  id_type       ENUM('national_id','passport','driving_permit','other') NULL,
  id_number     VARCHAR(60)  NULL,
  photo_path    VARCHAR(255) NULL,
  face_embedding_enc VARBINARY(2200) NULL,      -- for face-match check-out (optional, expires)
  watchlist_status ENUM('none','watch','blocked') NOT NULL DEFAULT 'none',
  watchlist_reason VARCHAR(255) NULL,
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version       INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at    DATETIME(3)  NULL,
  PRIMARY KEY (id),
  KEY ix_visitors_idno (school_id, id_number),
  KEY ix_visitors_phone (school_id, phone),
  KEY ix_visitors_watch (school_id, watchlist_status),
  CONSTRAINT fk_visitors_school FOREIGN KEY (school_id) REFERENCES schools(id)
) ENGINE=InnoDB;

CREATE TABLE visits (
  id             CHAR(36)     NOT NULL,
  school_id      CHAR(36)     NOT NULL,
  visitor_id     CHAR(36)     NOT NULL,
  host_user_id   CHAR(36)     NULL,
  host_name      VARCHAR(150) NULL,
  purpose        VARCHAR(255) NOT NULL,
  vehicle_plate  VARCHAR(20)  NULL,
  status         ENUM('preregistered','checked_in','checked_out','cancelled','denied') NOT NULL,
  expected_at    DATETIME(3)  NULL,
  checked_in_at  DATETIME(3)  NULL,
  checked_out_at DATETIME(3)  NULL,
  checkout_method ENUM('qr','face','manual') NULL,
  max_duration_min SMALLINT UNSIGNED NOT NULL DEFAULT 120,   -- overstay threshold
  entry_device_id CHAR(36)    NULL,
  created_by     CHAR(36)     NULL,
  created_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version        INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at     DATETIME(3)  NULL,
  PRIMARY KEY (id),
  KEY ix_visits_status (school_id, status, checked_in_at),   -- "on campus now" / overstay
  KEY ix_visits_visitor (visitor_id, checked_in_at),
  KEY ix_visits_host (host_user_id),
  CONSTRAINT fk_visits_visitor FOREIGN KEY (visitor_id)   REFERENCES visitors(id),
  CONSTRAINT fk_visits_host    FOREIGN KEY (host_user_id) REFERENCES users(id),
  CONSTRAINT fk_visits_device  FOREIGN KEY (entry_device_id) REFERENCES devices(id),
  CONSTRAINT fk_visits_creator FOREIGN KEY (created_by)   REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE badges (
  id          CHAR(36)    NOT NULL,
  school_id   CHAR(36)    NOT NULL,
  visit_id    CHAR(36)    NOT NULL,
  badge_no    VARCHAR(20) NOT NULL,
  qr_token    CHAR(32)    NOT NULL,
  printed_at  DATETIME(3) NULL,
  returned_at DATETIME(3) NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version     INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at  DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_badges_qr (qr_token),
  UNIQUE KEY uq_badges_no (school_id, badge_no),
  KEY ix_badges_visit (visit_id),
  CONSTRAINT fk_badges_visit FOREIGN KEY (visit_id) REFERENCES visits(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- notifications_queue
CREATE TABLE notifications_queue (
  id            CHAR(36)     NOT NULL,
  school_id     CHAR(36)     NOT NULL,
  guardian_id   CHAR(36)     NULL,
  student_id    CHAR(36)     NULL,
  channel       ENUM('sms','email','whatsapp') NOT NULL,
  recipient     VARCHAR(190) NOT NULL,
  template      VARCHAR(60)  NOT NULL,          -- 'arrived','late','absent','departed'
  payload       JSON         NOT NULL,
  dedupe_key    VARCHAR(120) NOT NULL,          -- e.g. student+date+template: prevents duplicate sends
  status        ENUM('queued','sending','sent','failed','cancelled') NOT NULL DEFAULT 'queued',
  attempts      TINYINT UNSIGNED NOT NULL DEFAULT 0,
  next_attempt_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_error    VARCHAR(255) NULL,
  sent_at       DATETIME(3)  NULL,
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version       INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at    DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_nq_dedupe (school_id, dedupe_key),
  KEY ix_nq_due (status, next_attempt_at),
  CONSTRAINT fk_nq_guardian FOREIGN KEY (guardian_id) REFERENCES guardians(id),
  CONSTRAINT fk_nq_student  FOREIGN KEY (student_id)  REFERENCES students(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- sync_outbox (edge -> central)
-- Written in the SAME transaction as the business change. NOT itself synced.
CREATE TABLE sync_outbox (
  seq            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,   -- local ordering only
  event_id       CHAR(36)     NOT NULL,                     -- idempotency key
  school_id      CHAR(36)     NOT NULL,
  entity         VARCHAR(40)  NOT NULL,                     -- table name
  entity_id      CHAR(36)     NOT NULL,
  op             ENUM('insert','update','delete') NOT NULL,
  entity_version INT UNSIGNED NOT NULL,
  payload        JSON         NOT NULL,                     -- full row snapshot
  occurred_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  status         ENUM('pending','sending','acked','dead') NOT NULL DEFAULT 'pending',
  attempts       INT UNSIGNED NOT NULL DEFAULT 0,
  next_attempt_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_error     VARCHAR(255) NULL,
  acked_at       DATETIME(3)  NULL,
  PRIMARY KEY (seq),
  UNIQUE KEY uq_outbox_event (event_id),
  KEY ix_outbox_pending (status, next_attempt_at, seq),
  KEY ix_outbox_entity (entity, entity_id)
) ENGINE=InnoDB;

-- Sync bookkeeping: pull cursor (central -> edge) and idempotent receipt log (central side).
CREATE TABLE sync_state (
  school_id      CHAR(36)    NOT NULL,
  pull_cursor    BIGINT UNSIGNED NOT NULL DEFAULT 0,        -- last central change_seq applied
  last_push_at   DATETIME(3) NULL,
  last_pull_at   DATETIME(3) NULL,
  last_success_at DATETIME(3) NULL,
  PRIMARY KEY (school_id)
) ENGINE=InnoDB;

CREATE TABLE sync_inbox (            -- central: events already applied (dedupe + audit)
  event_id    CHAR(36)    NOT NULL,
  school_id   CHAR(36)    NOT NULL,
  received_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  result      ENUM('applied','skipped_stale','conflict_resolved') NOT NULL,
  PRIMARY KEY (event_id),
  KEY ix_inbox_school (school_id, received_at)
) ENGINE=InnoDB;

CREATE TABLE sync_changes (          -- central: ordered change feed served to edges on pull
  change_seq  BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  school_id   CHAR(36)    NOT NULL,
  entity      VARCHAR(40) NOT NULL,
  entity_id   CHAR(36)    NOT NULL,
  op          ENUM('insert','update','delete') NOT NULL,
  entity_version INT UNSIGNED NOT NULL,
  payload     JSON        NOT NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (change_seq),
  KEY ix_changes_school (school_id, change_seq)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- audit_logs (immutable, hash-chained)
CREATE TABLE audit_logs (
  id          CHAR(36)     NOT NULL,
  school_id   CHAR(36)     NULL,
  actor_id    CHAR(36)     NULL,
  actor_kind  ENUM('user','device','system') NOT NULL DEFAULT 'user',
  action      VARCHAR(80)  NOT NULL,            -- 'attendance.override','student.export','login.failed'
  entity      VARCHAR(40)  NULL,
  entity_id   CHAR(36)     NULL,
  detail      JSON         NULL,
  ip_address  VARCHAR(45)  NULL,
  occurred_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  prev_hash   CHAR(64)     NOT NULL,            -- tamper-evidence chain
  row_hash    CHAR(64)     NOT NULL,            -- SHA-256(prev_hash || canonical row)
  PRIMARY KEY (id),
  KEY ix_audit_time   (school_id, occurred_at),
  KEY ix_audit_actor  (actor_id, occurred_at),
  KEY ix_audit_entity (entity, entity_id)
) ENGINE=InnoDB;

-- DB-level immutability: no UPDATE / DELETE on audit_logs, ever.
DELIMITER $$
CREATE TRIGGER trg_audit_no_update BEFORE UPDATE ON audit_logs
FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit_logs is immutable'; END$$
CREATE TRIGGER trg_audit_no_delete BEFORE DELETE ON audit_logs
FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit_logs is immutable'; END$$
DELIMITER ;

-- ---------------------------------------------------------------- settings
CREATE TABLE settings (
  id          CHAR(36)     NOT NULL,
  school_id   CHAR(36)     NULL,               -- NULL = global default
  `key`       VARCHAR(80)  NOT NULL,
  `value`     JSON         NOT NULL,
  updated_by  CHAR(36)     NULL,
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version     INT UNSIGNED NOT NULL DEFAULT 1,
  deleted_at  DATETIME(3)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_settings (school_id, `key`),
  CONSTRAINT fk_settings_school FOREIGN KEY (school_id) REFERENCES schools(id),
  CONSTRAINT fk_settings_user   FOREIGN KEY (updated_by) REFERENCES users(id)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------- migration bookkeeping
CREATE TABLE schema_migrations (
  version     VARCHAR(20) NOT NULL,
  description VARCHAR(200) NOT NULL,
  applied_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (version)
) ENGINE=InnoDB;
INSERT INTO schema_migrations (version, description) VALUES ('V001', 'initial schema');

SET FOREIGN_KEY_CHECKS = 1;
